import ipaddress
from socket import AF_INET6, AF_INET, socket


def get_socket(host: str, port: int, initial_timeout: int, general_timeout: int) -> socket:
    """Create a socket configured for IPv6 or IPv4 based on host.

    :param host: IP address.
    :param port: port which IP address is to be bind to.
    :param initial_timeout: timeout for socket connection establishement.
    :param general_timeout: timeout for socket operation, transmission actions."""
    family = AF_INET
    if isinstance(ipaddress.ip_address(host), ipaddress.IPv6Address):
        family = AF_INET6
    sock = socket(family)
    sock.settimeout(initial_timeout)
    sock.connect((host, port))
    sock.settimeout(general_timeout)
    return sock


def get_socket_family(host: str) -> AF_INET | AF_INET6:
    """Get socket family based on host.

    :param host: IP address.
    """
    return AF_INET6 if isinstance(ipaddress.ip_address(host), ipaddress.IPv6Address) else AF_INET
